<script>
(function(){
function g(id){return document.getElementById(id)}
function esc(v){if(v==null)return'';return String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function qa(s,r){return Array.prototype.slice.call((r||document).querySelectorAll(s))}

var L='en';
var raw=g('rlraw');var d=null;
if(raw&&raw.value.trim()){
  var dec=document.createElement('textarea');dec.innerHTML=raw.value.trim();
  try{d=JSON.parse(dec.value.trim())}catch(e){}
}
if(!d)d={};

function t(en,th){return L==='th'?th:en}

function shardPts(ang,rTip,rBase,hw){
  var rad=ang*Math.PI/180,rad1=(ang-hw)*Math.PI/180,rad2=(ang+hw)*Math.PI/180;
  var tx=100+Math.cos(rad)*rTip,ty=100+Math.sin(rad)*rTip;
  var b1x=100+Math.cos(rad1)*rBase,b1y=100+Math.sin(rad1)*rBase;
  var b2x=100+Math.cos(rad2)*rBase,b2y=100+Math.sin(rad2)*rBase;
  return tx+','+ty+' '+b1x+','+b1y+' '+b2x+','+b2y;
}

function buildBurst(color){
  var shards='',cracks='';
  for(var i=0;i<8;i++){
    var ang=i*45;
    var rTip=(i%2===0)?82:64;
    shards+='<polygon class="rl-shard" points="'+shardPts(ang,rTip,26,9)+'" fill="'+color+'" opacity="'+(i%2===0?.85:.55)+'"/>';
    var cang=ang+22.5;
    var rad=cang*Math.PI/180;
    var x1=100+Math.cos(rad)*58,y1=100+Math.sin(rad)*58;
    var x2=100+Math.cos(rad)*92,y2=100+Math.sin(rad)*92;
    cracks+='<line class="rl-crack" x1="'+x1+'" y1="'+y1+'" x2="'+x2+'" y2="'+y2+'" stroke="var(--gold)" stroke-width="1"/>';
  }
  return ''+
  '<svg viewBox="0 0 200 200">'+shards+cracks+'</svg>'+
  '<svg viewBox="0 0 200 200">'+
    '<defs><radialGradient id="coreg" cx="50%" cy="50%" r="60%">'+
      '<stop offset="0%" stop-color="#fff" stop-opacity=".95"/>'+
      '<stop offset="35%" stop-color="'+color+'"/>'+
      '<stop offset="100%" stop-color="'+color+'" stop-opacity="0"/>'+
    '</radialGradient></defs>'+
    '<circle id="rl-core" cx="100" cy="100" r="30" fill="url(#coreg)"/>'+
